        int count = 0;
        for(int j=0;j<words[i].size();j++){
            bool found = false;
            for(int k=0;k<words[i].size();k++){
                if(words[i][j] == words[i][k]){
                    found = true;
                    break;
                }
            }
            if(!found){
                count++;
            }
        }
        if(count > max_count){
            max_count = count;
            max_word = words[i];
        }
        else if(count == max_count && words[i] < max_word){
            max_word = words[i];
        }
    }
    return max_word;
}

